import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        ArrayList<Integer> 本地仓库 = new ArrayList<>();
        int 去仓次数 = 0;
        for (int k = 1; k <= n; k++) {
            int 货号 = sc.nextInt();
            boolean 见过 = false;
            for (int i = 0; i < 本地仓库.size(); i++) {
                if (本地仓库.get(i) == 货号) {
                    见过 = true;
                }
            }
            if (见过) {
                System.out.println("第 " + k + " 件：从本地仓库拿");
            } else {
                本地仓库.add(货号);
                去仓次数 = 去仓次数 + 1;
                System.out.println("第 " + k + " 件：去中央仓库搬");
            }
        }
        System.out.println("一共去了中央仓库 " + 去仓次数 + " 趟");
    }
}
